// Minimal custom SRP (simplified for understanding)
using UnityEngine;
using UnityEngine.Rendering;

public class MinimalRenderPipeline : RenderPipeline
{
    protected override void Render(
        ScriptableRenderContext context, 
        Camera[] cameras)
    {
        foreach (Camera camera in cameras)
        {
            // 1. Cull objects visible to this camera
            ScriptableCullingParameters cullingParams;
            camera.TryGetCullingParameters(out cullingParams);
            CullingResults cull = context.Cull(ref cullingParams);

            // 2. Set up render target (the screen)
            context.SetupCameraProperties(camera);

            // 3. Clear the screen
            CommandBuffer cmd = new CommandBuffer();
            cmd.ClearRenderTarget(true, true, Color.black);
            context.ExecuteCommandBuffer(cmd);
            cmd.Release();

            // 4. Draw visible objects
            ShaderTagId shaderTag = new ShaderTagId("SRPDefaultUnlit");
            SortingSettings sortSettings = new SortingSettings(camera);
            DrawingSettings drawSettings = new DrawingSettings(
                shaderTag, sortSettings);
            FilteringSettings filterSettings = new FilteringSettings(
                RenderQueueRange.opaque);

            context.DrawRenderers(
                cull, ref drawSettings, ref filterSettings);

            // 5. Submit everything to GPU
            context.Submit();
        }
    }
}

