// Step 1: Create the Renderer Feature
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class CustomOutlineFeature : ScriptableRendererFeature
{
    // Settings exposed in the Inspector
    [System.Serializable]
    public class OutlineSettings
    {
        public RenderPassEvent renderPassEvent = RenderPassEvent.AfterRenderingOpaques;
        public Material outlineMaterial;
    }

    public OutlineSettings settings = new OutlineSettings();
    private OutlinePass outlinePass;

    // Called when the feature is created
    public override void Create()
    {
        outlinePass = new OutlinePass(settings);
    }

    // Called every frame to add passes to the renderer
    public override void AddRenderPasses(
        ScriptableRenderer renderer, 
        ref RenderingData renderingData)
    {
        // Inject our custom pass into the pipeline
        renderer.EnqueuePass(outlinePass);
    }
}

// Step 2: Create the Render Pass
public class OutlinePass : ScriptableRenderPass
{
    private OutlineSettings settings;
    private RenderTargetIdentifier source;
    private RenderTargetHandle tempTexture;

    public OutlinePass(OutlineSettings settings)
    {
        this.settings = settings;
        // When in the pipeline this pass runs
        renderPassEvent = settings.renderPassEvent;
        tempTexture.Init("_TempOutlineTexture");
    }

    public override void Execute(
        ScriptableRenderContext context, 
        ref RenderingData renderingData)
    {
        CommandBuffer cmd = CommandBufferPool.Get("Outline Pass");

        // Get the camera's color buffer
        RenderTargetIdentifier cameraColorTarget = 
            renderingData.cameraData.renderer.cameraColorTarget;

        // Create a temporary render texture
        RenderTextureDescriptor descriptor = 
            renderingData.cameraData.cameraTargetDescriptor;
        cmd.GetTemporaryRT(tempTexture.id, descriptor);

        // Blit from camera target to temp texture using our material
        // The shader in the material does the outline effect
        cmd.Blit(cameraColorTarget, tempTexture.Identifier(), 
                 settings.outlineMaterial);

        // Blit back to camera target
        cmd.Blit(tempTexture.Identifier(), cameraColorTarget);

        // Execute and clean up
        context.ExecuteCommandBuffer(cmd);
        CommandBufferPool.Release(cmd);
    }

    public override void FrameCleanup(CommandBuffer cmd)
    {
        cmd.ReleaseTemporaryRT(tempTexture.id);
    }
}

