// GPU Instancing example in C#
public class GrassSpawner : MonoBehaviour
{
    public Mesh grassMesh;
    public Material grassMaterial;
    private Matrix4x4[] matrices = new Matrix4x4[1023];

    void Update()
    {
        // Fill matrices with transforms for each grass blade
        for (int i = 0; i < 1023; i++)
        {
            Vector3 pos = new Vector3(
                Random.Range(-50f, 50f), 0, Random.Range(-50f, 50f));
            matrices[i] = Matrix4x4.TRS(pos, Quaternion.identity, Vector3.one);
        }

        // Draw all 1023 grass blades in ONE draw call!
        Graphics.DrawMeshInstanced(
            grassMesh, 0, grassMaterial, matrices);
    }
}

