// Standard alpha blending in a URP shader
// This is what happens in the fragment shader for transparent objects

// Sample the texture (includes alpha channel)
float4 texColor = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, uv);

// Apply material color
float4 finalColor = texColor * _BaseColor;

// The alpha value controls transparency
// 1.0 = fully opaque, 0.0 = fully transparent
//
// URP handles the actual blending in the render state:
// Blend SrcAlpha OneMinusSrcAlpha
//
// This means:
// FinalColor = (ObjectColor * ObjectAlpha) + (BackgroundColor * (1 - ObjectAlpha))
//
// Example: Object is 50% transparent red (1, 0, 0, 0.5)
// Background is white (1, 1, 1)
// Result = (red * 0.5) + (white * 0.5) = pink (1, 0.5, 0.5)

// Shader queue controls render order in URP:
//
// Tags { "Queue" = "Geometry" }     → Opaque queue (drawn first)
// Tags { "Queue" = "AlphaTest" }     → Alpha tested/cutout (after opaque)
// Tags { "Queue" = "Transparent" }  → Transparent queue (drawn last)
//
// Within each queue, objects are sorted:
// - Opaque: front-to-back (closest first, for early-z optimization)
// - Transparent: back-to-front (farthest first, for correct blending)
//
// You can also use custom queue offsets:
// Tags { "Queue" = "Transparent+100" } → drawn after other transparent objects
//
// In the Material Inspector, you can see and change the Render Queue.
// Lower numbers = drawn earlier.
// Background (1000) → Geometry (2000) → AlphaTest (2450) →
// Transparent (3000) → Overlay (4000)

