    public Material monitorMaterial;
    private RenderTexture renderTex;

    void Start()
    {
        // Create a 512x512 render texture
        renderTex = new RenderTexture(512, 512, 16);
        renderTex.name = "SecurityCameraFeed";

        // Assign to camera
        securityCam.targetTexture = renderTex;

        // Assign to monitor material
        monitorMaterial.mainTexture = renderTex;
